import { Component } from '@angular/core';
import { LeaveService } from '../../services/leave.service';
import { Leave } from '../../models/leave.model';

@Component({
  selector: 'app-leave-application',
  templateUrl: './leave-application.component.html',
  styleUrls: ['./leave-application.component.css']
})
export class LeaveApplicationComponent {
  leave: Leave = {
    employeeId: 0, // Default Employee ID (Change as needed)
    leaveType: '',
    startDate: '',
    endDate: '',
    status: 'Pending' // Default status
  };

  constructor(private leaveService: LeaveService) {}

  applyLeave() {
    console.log('Submitting Leave:', this.leave); // ✅ Log before sending request
  
    this.leaveService.applyLeave(this.leave).subscribe(
      response => {
        console.log('API Response:', response); // ✅ Log successful response
        alert('Leave Applied Successfully!');
      },
      error => {
        console.error('API Error:', error); // ❌ Log error response
        alert('Failed to apply leave');
      }
    );
  }
  
    
  }

<h2>Apply for Leave</h2>
<form (ngSubmit)="applyLeave()">
  <label>Employee ID:</label>
  <input type="number" [(ngModel)]="leave.employeeId" name="employeeId" required />

  <label>Leave Type:</label>
  <input type="text" [(ngModel)]="leave.leaveType" name="leaveType" required />

  <label>Start Date:</label>
  <input type="date" [(ngModel)]="leave.startDate" name="startDate" required />

  <label>End Date:</label>
  <input type="date" [(ngModel)]="leave.endDate" name="endDate" required />

  <label>Status:</label>
  <select [(ngModel)]="leave.status" name="status">
    <option value="Pending">Pending</option>
    <option value="Approved">Approved</option>
    <option value="Rejected">Rejected</option>
  </select>

  <button type="submit">Apply Leave</button>
</form>
